#!/usr/bin/env python3
"""Produce reviewable study tables after inference and scoring have ended."""

from collections import Counter
import datetime as dt
import json
from pathlib import Path

from analyze_full import read_jsonl


ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "results/full"
NAMES = {"math": "MATH", "gsm8k": "GSM8K", "humaneval": "HumanEval", "bbh": "BBH"}


def f(value, digits=1):
    return "—" if value is None else f"{value:,.{digits}f}"


def pct(value):
    return "—" if value is None else f"{value * 100:.1f}%"


def pvalue(value):
    return "—" if value is None else f"{value:.2e}" if value < 0.0001 else f"{value:.4f}"


def interval(values, scale=1, digits=1):
    return "—" if not values or values[0] is None else f"[{values[0] * scale:.{digits}f}, {values[1] * scale:.{digits}f}]"


def table(headers, rows):
    return "\n".join(["| " + " | ".join(headers) + " |", "| " + " | ".join(["---"] * len(headers)) + " |", *["| " + " | ".join(str(x) for x in row) + " |" for row in rows]])


def main():
    a = json.loads((OUT / "analysis.json").read_text())
    state = json.loads((OUT / "job-state.json").read_text())
    assert state["stage"] in ["COMPLETED", "ERROR", "CANCELED", "CANCELLED"]
    config = json.loads((ROOT / "full-config.json").read_text())
    audit = json.loads((OUT / "audit.json").read_text())
    conditions = a["conditions"]
    main_rows = sorted([r for r in conditions if r["repeat"] == 0 and not r["share_cache"]], key=lambda r: (list(NAMES).index(r["domain"]), r["passes"]))
    lookup = {(r["domain"], r["passes"], r["share_cache"], r["repeat"]): r for r in conditions}
    ledger = read_jsonl(OUT / "modal-ledger.jsonl")
    modal_upper = sum(r["cost_upper_usd"] for r in ledger) + json.loads((OUT / "modal-preflight.json").read_text())["cost_upper_usd"]
    gpu_upper = state["conservative_cost_upper_usd"]
    wall_seconds = state["terminal_observed_epoch"] - state["submitted_epoch"]
    summary_path = OUT / "summary.json"
    remote_summary = json.loads(summary_path.read_text()) if summary_path.exists() else {}
    budget = {"opening_hf_credit_usd_user_reported": 24.40, "hf_gpu_cost_upper_usd": gpu_upper, "modal_cost_upper_usd": modal_upper, "full_study_cost_upper_usd": gpu_upper + modal_upper, "full_study_cap_usd": 15, "gpu_job_elapsed_seconds_upper": wall_seconds, "gpu_job_elapsed_hours_upper": wall_seconds / 3600, "prelaunch_nominal_usd": 12.830716, "gpu_job_id": state["job_id"], "hf_billing_api_available": False, "invoice_verified": False, "prior_pilot_cost_upper_usd": 0.595829, "worker_elapsed_seconds": remote_summary.get("total_worker_seconds"), "peak_gpu_memory_mib": remote_summary.get("peak_gpu_memory_mib")}
    preflight = json.loads((OUT / "modal-preflight.json").read_text())
    resource_start = min([state["submitted_epoch"], preflight["created_epoch"], *[r["started_epoch"] for r in ledger]])
    resource_end = max([state["terminal_observed_epoch"], *[r["terminated_epoch"] for r in ledger]])
    events = read_jsonl(OUT / "events.jsonl")
    budget.update(paid_resource_window_seconds=resource_end - resource_start, scored_inference_batch_seconds=sum(r["batch_wall_seconds"] or 0 for r in conditions), server_startup_seconds=sum(e["startup_seconds"] for e in events if e["kind"] == "server_ready"))
    budget["provisioning_warmup_flush_shutdown_and_observation_seconds"] = wall_seconds - budget["scored_inference_batch_seconds"] - budget["server_startup_seconds"]
    user_billing = OUT / "user-billing.json"
    if user_billing.exists():
        budget["user_billing"] = json.loads(user_billing.read_text())
    (OUT / "budget-report.json").write_text(json.dumps(budget, indent=2) + "\n")
    assert budget["full_study_cost_upper_usd"] <= 15, budget
    accuracy_table = table(["Domain", "Passes", "Correct / scored", "Accuracy (95% Wilson CI)", "Literal match", "Mean reasoning / answer", "Median reasoning / answer"], [[NAMES[r["domain"]], r["passes"], f"{r['correct']}/{r['n_scored']}", pct(r["accuracy"]) + " " + interval(r["wilson_95"], 100), pct(r.get("raw_string_match_accuracy")), f(r["mean_reasoning_tokens"]) + " / " + f(r["mean_answer_tokens"]), f(r["median_reasoning_tokens"]) + " / " + f(r["median_answer_tokens"])] for r in main_rows])
    speed_table = table(["Domain", "Passes", "Tokens/s", "Batch seconds", "Mean request s", "Effective decode ms/token", "GPU s/correct", "Inference $/correct", "Tokens/correct"], [[NAMES[r["domain"]], r["passes"], f(r["aggregate_tokens_per_second"], 0), f(r["batch_wall_seconds"]), f(r["mean_request_wall_seconds"]), f(r["mean_effective_decode_seconds_per_token"] * 1000 if r["mean_effective_decode_seconds_per_token"] else None, 2), f(r["gpu_seconds_per_correct"], 3), f(r["inference_usd_per_correct"], 6), f(r["tokens_per_correct"], 0)] for r in main_rows])
    primary = [r for r in a["paired_comparisons"] if r["domain"] == "math" and r["comparison"] == "separate" and r["from_passes"] == 3 and r["to_passes"] > 3 and r.get("mcnemar")]
    paired_table = table(["MATH comparison", "Δ accuracy pp (paired 95% CI)", "Gains / losses", "Exact McNemar p", "Holm p", "Δ reasoning tokens (paired 95% CI)"], [[f"3 → {r['to_passes']}", f(r["accuracy_difference"] * 100) + " " + interval(r["accuracy_difference_95"], 100), f"{r['mcnemar']['gains']} / {r['mcnemar']['losses']}", f(r["mcnemar"]["exact_two_sided_p"], 4), f(r["mcnemar"].get("holm_p_for_math_3_vs_4_5_6"), 4), f(r["reasoning_tokens"]["mean_difference"]) + " " + interval(r["reasoning_tokens"]["difference_95"])] for r in primary])
    compressions = [r for r in a["paired_comparisons"] if r["comparison"] == "separate" and r["from_passes"] == 1 and r["to_passes"] == 3 and r.get("reasoning_tokens")]
    compression_table = table(["Domain, 1 → 3", "Paired n", "Δ reasoning tokens (95% CI)", "Relative change (95% CI)", "Δ accuracy pp", "McNemar p"], [[NAMES[r["domain"]], r["n"], f(r["reasoning_tokens"]["mean_difference"]) + " " + interval(r["reasoning_tokens"]["difference_95"]), pct(r["reasoning_tokens"]["relative_mean_change"]) + " " + interval(r["reasoning_tokens"]["relative_change_95"], 100), f(r.get("accuracy_difference", 0) * 100), pvalue(r.get("mcnemar", {}).get("exact_two_sided_p"))] for r in compressions])
    sensitivity_table = table(["Domain, 1 → 3", "Both-correct n", "Mean reasoning 1 / 3", "Δ tokens (paired 95% CI)"], [[NAMES[r["domain"]], r["reasoning_sensitivity"]["both_correct"]["n"], f(r["reasoning_sensitivity"]["both_correct"]["mean_before"]) + " / " + f(r["reasoning_sensitivity"]["both_correct"]["mean_after"]), f(r["reasoning_sensitivity"]["both_correct"]["mean_difference"]) + " " + interval(r["reasoning_sensitivity"]["both_correct"]["difference_95"])] for r in compressions if "both_correct" in r["reasoning_sensitivity"]])
    shared = [r for r in a["paired_comparisons"] if r["comparison"] == "shared_vs_separate" and r.get("n")]
    cache_table = table(["Domain", "Passes", "Separate / shared accuracy", "Δ accuracy pp", "Gains / losses; p", "Separate / shared reasoning", "Separate / shared tokens/s"], [[NAMES[r["domain"]], r["from_passes"], pct(lookup[(r["domain"], r["from_passes"], False, 0)]["accuracy"]) + " / " + pct(lookup[(r["domain"], r["from_passes"], True, 0)]["accuracy"]), f(r.get("accuracy_difference", 0) * 100), f"{r.get('mcnemar', {}).get('gains', '—')} / {r.get('mcnemar', {}).get('losses', '—')}; {f(r.get('mcnemar', {}).get('exact_two_sided_p'), 4)}", f(lookup[(r["domain"], r["from_passes"], False, 0)]["mean_reasoning_tokens"]) + " / " + f(lookup[(r["domain"], r["from_passes"], True, 0)]["mean_reasoning_tokens"]), f(lookup[(r["domain"], r["from_passes"], False, 0)]["aggregate_tokens_per_second"], 0) + " / " + f(lookup[(r["domain"], r["from_passes"], True, 0)]["aggregate_tokens_per_second"], 0)] for r in shared])
    repeat_table = table(["Domain", "Passes", "Shared n", "Run accuracies", "Range / SD pp", "Hierarchical accuracy 95% CI", "Score flips vs run 0", "Exact output agreement vs run 0"], [[NAMES[r["domain"]], r["passes"], r["paired_n"], ", ".join(pct(x) for x in r["run_accuracies"]), f(r["accuracy_range_pp"], 2) + " / " + f(r["accuracy_std_pp"], 2), interval(r["hierarchical_accuracy_95"], 100), str(r["score_flips"]), ", ".join(pct(x) for x in r["exact_output_agreement"])] for r in a["repeat_noise"]])
    level_table = table(["MATH level", *[f"Pass {p}" for p in range(1, 7)]], [[level, *[f(next((r["mean_reasoning_tokens"] for r in a["math_difficulty"]["level_means"] if r["level"] == level and r["passes"] == p), None)) for p in range(1, 7)]] for level in range(1, 6)])
    interactions = table(["Pass comparison", "Hard minus easy absolute token change (95% CI)", "Hard minus easy relative change pp (95% CI)"], [[f"{r['from_passes']} → {r['to_passes']}", f(r.get("hard_minus_easy_absolute_difference")) + " " + interval(r.get("hard_minus_easy_absolute_95")), f(r.get("hard_minus_easy_relative_change", 0) * 100) + " " + interval(r.get("hard_minus_easy_relative_95"), 100)] for r in a["math_difficulty"]["paired_effects"]])
    matches = [r for r in a["observational_compute_matches"]["comparisons"] if r["relative_compute_tolerance"] == 0.1]
    matches_table = table(["Domain", "Pass comparison", "Matched n", "Δ accuracy pp", "Δ reasoning tokens"], [[NAMES[r["domain"]], f"{r['from_passes']} → {r['to_passes']}", r["n"], f(r.get("accuracy_difference", 0) * 100), f(r["reasoning_tokens"]["mean_difference"])] for r in matches])
    tradeoffs = [r for r in a["observational_compute_matches"]["batch_tradeoffs"] if (r["from_passes"], r["to_passes"]) == (1, 3) or r["domain"] == "math" and (r["from_passes"], r["to_passes"]) == (2, 3)]
    tradeoff_table = table(["Domain", "Passes", "Batch seconds, lower / higher", "Δ GPU wall time", "Δ reasoning length", "Δ accuracy pp", "Within 10% wall budget"], [[NAMES[r["domain"]], f"{r['from_passes']} → {r['to_passes']}", f(r["from_batch_seconds"]) + " / " + f(r["to_batch_seconds"]), pct(r["batch_wall_relative_change"]), pct(r["reasoning_relative_change"]), f(r["accuracy_difference"] * 100 if r["accuracy_difference"] is not None else None), r["within_10_percent_batch_wall_time"]] for r in tradeoffs])
    status = "Complete" if a["n_outputs"] == a["expected_inference_outputs"] and a["n_scored"] == a["n_outputs"] else "Incomplete; see coverage audit"
    lines = ["# Loop Dial — full study", "", "**Checkpoint: thinkingmachines/TML-d24-varloop-research (varloop research checkpoint). These are not shipped Inkling 2 Mini results.**", "", f"{status}: {a['n_outputs']:,}/{a['expected_inference_outputs']:,} authorized responses saved and {a['n_scored']:,} scored. No follow-up model inference is authorized or launched.", "", "## Main curve", "", accuracy_table, "", "Passes 4–5 are **midtraining range, not RL'd**. Pass 6 is **beyond the trained range** and was measured only on MATH in the full study. Main results are the original run with separate caches; repeats are reported separately. MATH uses 40 problems per level, so its summary weights levels equally. GSM8K is primarily a length measurement.", "", "![Accuracy versus passes](results/full/charts/accuracy-vs-passes.png)", "", "## Does looping reduce written reasoning?", "", compression_table, "", "Intervals are paired problem-bootstrap intervals. Shorter visible text is evidence of output compression, not direct evidence about the content or faithfulness of hidden computation.", "", "![Output tokens versus passes](results/full/charts/tokens-vs-passes.png)", "", "## Where does extra depth stop helping?", "", paired_table, "", "These three MATH comparisons form the primary Holm-corrected family. All adjacent, 1→3, and shared-cache paired results, including token-change intervals, are in [analysis.json](results/full/analysis.json). A nonsignificant result does not establish equality, particularly near the accuracy ceiling.", "", "## Difficulty and reasoning length", "", "Mean reasoning tokens by level:", "", level_table, "", interactions, "", "Easy means levels 1–2; hard means levels 4–5. Negative hard-minus-easy relative change means more proportional shortening on hard problems. All per-level paired absolute and relative confidence intervals are saved in analysis.json.", "", "![MATH reasoning by difficulty](results/full/charts/math-difficulty-reasoning.png)", "", "## Shared versus separate caches", "", cache_table, "", "Cache comparisons use the same problems and a fresh server. Their McNemar tests are exploratory. Observed memory includes reserved pools; a smaller reservation is not a measurement of intrinsic per-request memory requirements.", "", "## Speed and cost per correct answer", "", speed_table, "", "GPU seconds/correct are domain-batch wall seconds divided by correct count. Per-condition dollars use $2.75/GPU-hour and exclude server loading and CPU grading. Request seconds include time while other requests run at C32; batch seconds/problem are amortized throughput costs, not interactive latency. Effective decode ms/token is a streaming first-to-last-text proxy. Exact means, medians, accuracy/second, total tokens, truncations, memory peaks, and shared/repeat timing are in [metrics.csv](results/full/metrics.csv).", "", "![Accuracy versus amortized GPU time](results/full/charts/accuracy-vs-latency-pareto.png)", "", "## Repeat noise", "", repeat_table, "", "Each cell has three runs. MATH run 0 is restricted to the same nested 100-problem subset as repeats; HumanEval uses all 164. The range and SD describe only these three observations. Hierarchical run/problem CIs are saved in analysis.json. Repeated tasks are never counted as independent benchmark examples.", "", "## Observational compute matching", "", matches_table, "", a["observational_compute_matches"]["method"], "", "The table uses the 10% band; the 5%/20% sensitivity subsets and IDs are retained in analysis.json. It cannot answer a causal comparison of fixed reasoning budgets. No additional generations were run for this analysis.", "", "## Pilot re-score and prior result", "", "The saved pilot scores 50/50 at passes 1, 3, and 6 under numeric equivalence, each with a Wilson 95% CI of 92.9%–100%. Literal match scores are 24/50, 24/50, and 25/50. The legacy reference grader gave 44/50, 44/50, and 47/50. See [PILOT_RESCORE.md](PILOT_RESCORE.md).", "", "The [SGLang cookbook](https://docs.sglang.io/cookbook/autoregressive/ThinkingMachines/Inkling-2-Mini) reports GSM8K 84.0% at one pass, 88.5% at three, and 90.0% at three with shared cache. The pilot's legacy 1/3-pass intervals (76.2%–94.4%) cover the corresponding figures, but that is only a rough 50-example check. The new numeric metric differs, and the cookbook's loop-options paragraph does not pin its model revision, subset, or prompt, so this is not an exact reproduction. The [official release](https://thinkingmachines.ai/news/inkling-2-mini/) already studies looping and shorter reasoning; this study adds this fixed multi-domain matrix, timing, cache and repeat measurements.", "", "## Budget and coverage", "", f"The HF job ended with status **{state['stage']}** after **{wall_seconds / 60:.2f} minutes** from submission to observed termination. Timestamp-based GPU cost upper bound: **${gpu_upper:.4f}**. Conservative Modal sandbox cost upper bound, including harness validation: **${modal_upper:.4f}**. Combined full-study upper bound: **${budget['full_study_cost_upper_usd']:.4f}**, below the $15 cap. These are resource-time bounds, not a verified invoice; billing API access is unavailable. Opening HF credits were user-reported at $24.40. The earlier approximately $0.60 pilot is separate.", "", f"The prelaunch forecast was $12.83 nominal and no budget cuts were applied. Inference errors: {audit['inference_errors']}; math-grader errors: {audit['grader_errors']}; sandbox infrastructure errors: {audit['sandbox_infrastructure_errors']}. Missing outputs: {len(audit['missing_keys'])}; missing score records: {len(audit['missing_score_keys'])}. See [audit.json](results/full/audit.json), [budget-report.json](results/full/budget-report.json), and [BUDGET.md](BUDGET.md).", "", "## Reproducibility and limits", "", "[METHODS.md](METHODS.md) defines prompts, scoring, statistics, sandbox limits, timing, and caveats. [full-config.json](full-config.json) and [data/full/manifest.json](data/full/manifest.json) freeze the matrix and sources. Raw responses, complete reasoning/answer text, token counts, usage, timings, and scores are in [scored-outputs.jsonl](results/full/scored-outputs.jsonl); [outputs.jsonl](results/full/outputs.jsonl) preserves inference records without grader edits. The as-launched runtime source and exact model revision are archived. PNG and SVG chart versions are in results/full/charts.", "", "Common public benchmark familiarity, the output cap, fixed execution order, three-repeat sample size, and finite-batch C32 throughput limit generalization. The confidence intervals describe sampling and observed repeat variation, not all sources of systematic error. Findings at six passes concern behavior beyond trained depth. No controlled token-budget sweep or extra post-study generations were run.", ""]
    text = "\n".join(lines)
    token_note = "Reasoning and answer columns count independently re-tokenized visible text. API reasoning counts usually differ by three tokens; all originals are retained. Using API reasoning counts gives one→three reductions of 41.3% MATH, 41.6% HumanEval, 29.8% GSM8K, and 25.2% BBH. Re-tokenization can occasionally exceed the generation cap by a token; these columns measure visible text length. See METHODS.md and the token audit."
    text = text.replace("![Accuracy versus passes]", token_note + "\n\n![Accuracy versus passes]", 1)
    text = text.replace("These three MATH comparisons form the primary Holm-corrected family.", "Accuracy-difference intervals use a percentile bootstrap and can have a zero boundary when no gain was observed; exact McNemar tests govern accuracy comparisons. These three MATH comparisons form the primary Holm-corrected family.")
    text = text.replace("## Reproducibility and limits", "Compute shutdown is verified: HF reports COMPLETED and the final Modal query returned zero active study sandboxes. All 1,804 generated-code executions completed without infrastructure or termination errors; all 164 canonical solutions passed harness validation.\n\n## Reproducibility and limits")
    if a.get("bbh_tasks"):
        breakdown = a["bbh_tasks"]
        task_table = table(["BBH task", "1 pass", "3 passes", "5 passes"], [[task, *[next((f"{r['correct']}/{r['n_scored']}" for r in breakdown if r["task"] == task and r["passes"] == p), "—") for p in [1, 3, 5]]] for task in sorted({r["task"] for r in breakdown})])
        text = text.replace("## Shared versus separate caches", "## Hard-reasoning task breakdown\n\n" + task_table + "\n\nThese small task cells help identify which task types drive the pooled BBH curve. They do not represent the full BBH suite or GPQA.\n\n## Shared versus separate caches")
    interpretation = OUT / "interpretation.md"
    if interpretation.exists():
        text = text.replace("## Main curve", interpretation.read_text().strip() + "\n\n## Main curve", 1)
    text = text.replace("## Observational compute matching", "## Observational compute matching\n\nWhole-cohort tradeoffs, using all the same problems and measured batch time:\n\n" + tradeoff_table + "\n\nThese observed timings were not held fixed by an explicit compute-budget control. The full pass-pair table is retained, including pairs with similar realized budgets. The separate length-selected proxy analysis follows.")
    text = text.replace("The prelaunch forecast was $12.83 nominal and no budget cuts were applied.", f"The paid-resource window, from first sandbox validation to last observed termination, was {budget['paid_resource_window_seconds'] / 60:.1f} minutes. GPU job time comprised {budget['scored_inference_batch_seconds'] / 60:.1f} minutes of scored batches, {budget['server_startup_seconds'] / 60:.1f} minutes of server startup, and {budget['provisioning_warmup_flush_shutdown_and_observation_seconds'] / 60:.1f} minutes for provisioning, warmup, cache flushing, shutdown and observation. The prelaunch forecast was $12.83 nominal and no budget cuts were applied.")
    peak = remote_summary.get("peak_gpu_memory_mib") or max((r["peak_gpu_memory_mib"] or 0 for r in conditions), default=0)
    text = text.replace("## Repeat noise", f"Peak sampled GPU memory across the study was **{f(peak, 0)} MiB ({f(peak / 1024, 2)} GiB)** on the 96 GB RTX PRO 6000. This BF16 runtime measurement includes reserved pools.\n\n## Repeat noise")
    text = text.replace("Intervals are paired problem-bootstrap intervals.", "To check whether shortening merely reflects fewer token-limit failures, here is the same comparison restricted to problems answered correctly in both settings:\n\n" + sensitivity_table + "\n\nThis is a descriptive sensitivity analysis selected by outcomes; the full-pair result remains primary. Nontruncated-pair sensitivity results are also retained in analysis.json. Intervals are paired problem-bootstrap intervals.")
    reference_path = OUT / "gsm8k-legacy-sanity.json"
    if reference_path.exists():
        reference = json.loads(reference_path.read_text())
        reference_table = table(["Full GSM8K subset", "Legacy reference score", "95% Wilson CI", "Cookbook value inside CI"], [[r["passes"], f"{r['correct']}/{r['scored']} ({pct(r['accuracy'])})", interval(r["wilson_95"], 100), r["reference_inside_ci"]] for r in reference["summary"]])
        text = text.replace("## Budget and coverage", "Full-subset legacy-reference sanity check (secondary, does not replace numeric-equivalence grading):\n\n" + reference_table + "\n\n## Budget and coverage")
    failures_path = OUT / "failure-examples.json"
    if failures_path.exists():
        failures = json.loads(failures_path.read_text())["examples"]
        chosen = []
        for passes in [4, 5, 6]:
            candidates = [r for r in failures if r["passes"] == passes]
            if candidates:
                chosen.append(max(candidates, key=lambda r: r["repeated_8word_phrase"]["occurrences"]))
                wrong = [r for r in candidates if r["failure_type"] == "wrong_final_answer"]
                if wrong and wrong[0] not in chosen:
                    chosen.append(wrong[0])
        failure_table = table(["MATH ID", "Passes", "Level", "Reasoning tokens at 3 / higher depth", "Failure"], [[r["id"], r["passes"], r["level"], f"{r['baseline_reasoning_tokens']} / {r['higher_depth_reasoning_tokens']}", r["failure_type"].replace("_", " ")] for r in chosen])
        examples_text = []
        repeated = next((r for r in chosen if r["failure_type"] == "repetition_until_token_limit"), None)
        wrong = next((r for r in chosen if r["failure_type"] == "wrong_final_answer"), None)
        if repeated:
            phrase = repeated["repeated_8word_phrase"]["phrase"][:120].replace("`", "'")
            examples_text.append(f"At {repeated['passes']} passes, `{repeated['id']}` repeated text such as `{phrase}` until the output cap, with no final answer. The three-pass response used {repeated['baseline_reasoning_tokens']} reasoning tokens and answered correctly.")
        if wrong:
            examples_text.append(f"At {wrong['passes']} passes, `{wrong['id']}` returned `{wrong['higher_depth_answer']}` against reference `{wrong['expected_answer']}`; three passes answered correctly.")
        text = text.replace("## Budget and coverage", "## Failure examples\n\nThese tasks were correct at three passes and failed at the higher depth shown. The repetition label requires at least ten occurrences of an identical eight-word phrase plus exhaustion of the token budget.\n\n" + failure_table + "\n\n" + "\n\n".join(examples_text) + "\n\n[Failure examples](results/full/failure-examples.json) retain all such MATH regressions, correct baseline answers, wrong or missing higher-depth answers, repeated phrases, and reasoning excerpts. Full traces remain in scored-outputs.jsonl. These examples illustrate failure modes and do not estimate their prevalence outside the measured subset.\n\n## Budget and coverage")
    (ROOT / "REPORT.md").write_text(text)
    start = dt.datetime.fromtimestamp(state["submitted_epoch"], dt.timezone.utc).isoformat()
    end = dt.datetime.fromtimestamp(state["terminal_observed_epoch"], dt.timezone.utc).isoformat()
    budget_text = ["# Loop Dial budget", "", "Full study: **thinkingmachines/TML-d24-varloop-research varloop research checkpoint**. Authorized cap **$15**, in addition to the completed pilot. Opening HF credits: **$24.40**, user-reported. No inference after this study is authorized.", "", table(["Item", "Measured / bounded cost"], [["HF RTX PRO 6000, one job", f"≤ ${gpu_upper:.6f}"], ["Modal CPU sandboxes including validation", f"≤ ${modal_upper:.6f}"], ["Full study combined", f"≤ ${gpu_upper + modal_upper:.6f}"], ["Completed prior pilot, separate", "≤ $0.595829 (about $0.60 from credit balance)"]]), "", f"HF job: [{state['job_id']}]({state['url']}). Submission {start}; terminal status observed {end}. Upper elapsed time {wall_seconds / 3600:.4f} GPU-hours. HF cost bound rounds elapsed submission-to-observation time up to whole minutes at $0.045833/minute. It includes provisioning, loading, warmup, inference, and shutdown observation; it is conservative relative to billable running time.", "", "Modal is CPU-only. Each isolated sandbox requests a fixed 0.5 CPU and 1 GiB. Its bound counts local create-to-termination time at $0.094716/hour, approximately three times the checked resource rate. Preflight, self-tests, canonical-solution validation, generated candidates, failed attempts, and termination time are included. No other Modal project is touched. Modal project cap remains $2.", "", "These are conservative resource-time estimates. HF billing API access was unavailable and no invoice has been read. A later user-reported final credit balance may establish the HF balance change, assuming no other HF usage; it does not verify Modal charges. Actual billed charges remain unverified.", "", "The prelaunch [FORECAST.md](FORECAST.md) estimated $12.83 nominal, comprising $12.08 GPU plus a $0.75 CPU reserve. It retained all 4,734 scored generations because nominal cost was below $13. Its length assumptions were 3,072 tokens at three passes for MATH/BBH and 1,024 for code, anchored to measured pilot rates. The forecast and ordered budget cuts are saved in [forecast.json](results/full/forecast.json).", "", "Enforcement reserved cleanup cost: worker deadline 290 minutes, provider timeout 295, local cancellation at 300, and an additional 10-minute liability reserve. At the checked rate, 310 GPU minutes plus $0.75 CPU reserve is $14.95823. Sandbox admission also enforces the shared total after GPU termination. No automatic paid model retries are allowed.", "", "The complete numerical ledger is [budget-report.json](results/full/budget-report.json). Raw job status history and sandbox resource-time entries are in results/full/job-state.json and results/full/modal-ledger.jsonl. Per-condition inference dollars/correct in REPORT.md exclude startup and grading; total bounds above include them.", ""]
